#!/bin/bash
#
# Generated by Infinity (witness verification, Terminal-Bench 3 separate verifier).
# The runtime grades behaviour: it restores pristine inputs, re-runs the
# deliverable on fresh seeded inputs and writes reward.txt / status.txt /
# record.json itself. This launcher only guarantees the two things a harness
# cannot do without:
#   1. a reward exists on every exit path (trap EXIT), and we always exit 0;
#   2. a runtime that never wrote its verdict is recorded as errored, not as 0.
#
set +e
mkdir -p /logs/verifier

finish() {
  trap - EXIT
  [ -f /logs/verifier/reward.txt ] || printf '0\n' > /logs/verifier/reward.txt
  [ -f /logs/verifier/status.txt ] || printf 'errored\n' > /logs/verifier/status.txt
  exit 0
}
trap finish EXIT

cd /tests || exit 0

PYTEST_ADDOPTS='' PYTHONPATH='' /usr/local/bin/python3 -I /tests/infinity_witness.py \
  --manifest /tests/witness.json \
  --app-root /app \
  --tests-root /tests \
  --logs /logs/verifier \
  --python /usr/local/bin/python3
